insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('nodal', 'advanced', 'module', 'm01-the-node', 1, 'Why does the meeting of the inflow curve and the outflow curve carry any physical meaning at all?', '["Because both curves are drawn from the same well test.", "Because the reservoir and the tubing are solved by one numerical routine, which forces their answers onto a common basis.", "Both curves give a pressure at the same node as a function of the same rate, so they can be compared.", "Because the inflow falls monotonically while the outflow curve turns back upwards again."]'::jsonb, 2, 'Cut the well anywhere else and the pair of statements changes, which is why the node has to be named before any rate is quoted.'),
  ('nodal', 'advanced', 'module', 'm01-the-node', 2, 'BONNY-7 has the larger absolute open flow yet produces less than FORCADOS-3. What does that comparison establish?', '["The tubing side decides the rate, not the reservoir.", "BONNY-7 must be operating below its own bubble point.", "The composite inflow used for BONNY-7 must be miscalibrated, because a larger open flow has to deliver a larger operating rate.", "Absolute open flow is quoted at a different drawdown for each of the two wells."]'::jsonb, 0, 'BONNY-7 runs at a fraction 0.31350017 of its open flow and FORCADOS-3 at 0.51378991 of its own, so the two wells are working their reservoirs very differently.'),
  ('nodal', 'advanced', 'module', 'm01-the-node', 3, 'How does the engine form the residual it actually solves on?', '["It takes the absolute gap between the two curves.", "It subtracts the inflow pressure from the outflow pressure at each rate, leaving one signed number in psi.", "It subtracts the outflow pressure from the inflow pressure, so that a shortfall of reservoir energy appears as a negative value.", "It divides the tubing requirement by the reservoir supply at each sampled rate."]'::jsonb, 1, 'Four situations collapse into four readings of one curve: a zero, a dip below zero and back, a dip that just touches, and a dip that never arrives.'),
  ('nodal', 'advanced', 'module', 'm01-the-node', 4, 'What is the consequence of forming that difference the other way round?', '["Nothing changes, since only the zeros matter.", "The crossings move to different rates, since a zero depends on the subtraction order.", "The residual keeps its magnitude but the reported crossing count doubles.", "Every stability verdict in the tier inverts while each one still reads as entirely plausible."]'::jsonb, 3, 'The roots are indeed unmoved by the choice of sign, which is precisely why the error survives every check that looks only at rates.'),
  ('nodal', 'advanced', 'module', 'm01-the-node', 5, 'FORCADOS-3 reads +575.820837 psi at its lowest sampled rate and +3284.465003 psi at its highest, with a minimum of -509.628610 psi between. How many crossings do those readings force?', '["Exactly two, because a continuous function with the same sign at both ends must cross an even number of times.", "None, since both end readings are positive.", "At least three, since the dip below zero contributes one crossing and each of the two positive end readings contributes a further one.", "One, because only the deepest excursion below zero can produce a root."]'::jsonb, 0, 'The same argument closes the other direction: FORCADOS-3 could never have returned a single crossing, whatever the solver reported.'),
  ('nodal', 'advanced', 'module', 'm01-the-node', 6, 'The golden deadWell case returns status dead with zero crossings. What does that status assert?', '["That production has been suspended at the wellhead.", "That the well flows at the origin, where the rate is zero and the two curves therefore agree on the reservoir pressure.", "That no rate satisfies both curves at once.", "That the reservoir pressure has fallen below the bubble point of the fluid."]'::jsonb, 2, 'Its residual reads 988.172727 psi at 30.0000 stb/d and 1940.762069 psi at 570.0000 stb/d, so the gap never comes close to closing.'),
  ('nodal', 'advanced', 'module', 'm01-the-node', 7, 'Raising the minimum of the analytic residual from -40.000000 psi to -0.100000 psi did what to the root separation?', '["It removed the second root entirely.", "It collapsed the separation from 400 stb/d to 20.000000 stb/d, a twentyfold loss for a change of tens of psi.", "It left the separation unchanged at 400 stb/d, since the roots of a parabola depend on its curvature and not on its depth.", "It moved both roots to higher rates while holding their separation fixed."]'::jsonb, 1, 'The wide instrument roots sit at 800.000000 and 1200.000000 stb/d, the pinched pair at 990.000000 and 1010.000000 stb/d, with nothing else altered between them.'),
  ('nodal', 'advanced', 'module', 'm01-the-node', 8, 'Where does the engine place the node, and what does that placement do to the wellhead pressure?', '["At the tubing shoe, leaving the wellhead pressure outside the cut.", "At the choke, upstream of the tubing string.", "At the wellhead itself, so the wellhead pressure becomes the unknown that the solver adjusts until the two curves finally agree.", "At the sandface, so the wellhead pressure is recovered afterwards from the traverse."]'::jsonb, 0, 'BONNY-7 is solved with 420 psia held at the top and FORCADOS-3 with 960 psia, and neither figure is ever varied by the solve itself.'),
  ('nodal', 'advanced', 'module', 'm01-the-node', 9, 'BONNY-7 shows a dead column of 2570 psia against a reservoir pressure of 2740 psia. What does that pair tell you first?', '["The well must have two crossings rather than one.", "The well is 170 psi short of what it needs to lift a static column.", "The drawdown available at the operating point is fixed at 170 psi by that difference.", "The column does not outweigh the reservoir at low rate, so this well''s residual begins on the negative side."]'::jsonb, 3, 'FORCADOS-3 inverts the reading with a dead column of 4310 psia standing 590 psi above a reservoir pressure of 3720 psia.'),
  ('nodal', 'advanced', 'module', 'm01-the-node', 10, 'Sweeping BONNY-7''s wellhead from 280 to 490 psia moves its dead column from 2430 to 2640 psia. Why one for one?', '["Because the dead column is defined at the open flow rate.", "Because the lightening constant and the friction constant are both calibrated against the wellhead pressure that was used.", "With no flow there is no friction, so the column adds a fixed weight to whatever pressure is held at the top.", "Because the inflow curve shifts by the same amount as the wellhead pressure."]'::jsonb, 2, 'Neither curve is otherwise touched, yet the operating rate falls from 1424.991968 to 1319.581001 stb/d as the well is pushed back up its own inflow.'),
  ('nodal', 'advanced', 'module', 'm01-the-node', 11, 'BONNY-7''s sampled tubing minimum misses the true one by -22.728631 stb/d but by only 0.76036884 psi. What follows?', '["The true minimum must lie outside the range that was sampled here.", "The rate at the minimum is the curve''s least reliable feature.", "The 37 point tubing curve is too coarse for any use, so both the minimum pressure and the operating rate need refining.", "The sampling error in rate feeds straight through into the reported operating rate."]'::jsonb, 1, 'FORCADOS-3 repeats the pattern from 65 points, missing by -31.814966 stb/d in rate and 0.25586360 psi in pressure.'),
  ('nodal', 'advanced', 'module', 'm01-the-node', 12, 'A colleague cuts the node downstream of a choke in order to study that choke. What has the choice cost?', '["The choke moves both curves at once, so its effect cannot be isolated.", "The solver can no longer converge on such a node.", "The rate that comes back will be wrong by the weight of the entire column, although the reported pressure stays correct.", "The residual gains a discontinuity at every rate where the choke goes critical."]'::jsonb, 0, 'A change of node should leave the rate standing and move the pressure, which is the quickest test of whether a reported pressure belongs to the node claimed.'),
  ('nodal', 'advanced', 'module', 'm01-the-node', 13, 'A converged node answer asserts several things. How many of them did the solver actually test?', '["None, since convergence is a numerical result only.", "All of them, because a residual driven to zero requires consistent inputs.", "Two, the pressure match and then the stability label of the crossing found.", "One, that the two curves read the same pressure there, while the inputs behind them go unchecked."]'::jsonb, 3, 'The untested list runs to the inflow fit, the tubing constants, the held wellhead pressure, the steady state assumption and the reach of the scan.'),
  ('nodal', 'advanced', 'module', 'm01-the-node', 14, 'BONNY-7 sits 585.899719 psi above its tubing minimum and FORCADOS-3 only 18.717814 psi. What is lost by reporting the status word alone?', '["The fraction of absolute open flow at which each well runs.", "Nothing of consequence, because a stable crossing on the rising limb behaves the same way whatever its distance from the minimum.", "The margin, since both read flowing on the friction limb while one of them sits barely clear of its minimum.", "The drawdown, which the status word replaces with a single flowing label."]'::jsonb, 2, 'Measured along the rate axis the same contrast reads 728.644315 stb/d of clearance against 281.389786 stb/d.'),
  ('nodal', 'advanced', 'module', 'm01-the-node', 15, 'On a well with two roots, which one belongs in the report, and what does that report quietly assume?', '["Either root, as steady state arithmetic cannot rank them.", "The upper root, and it assumes the well was lifted above the lower one.", "Whichever root the scan reaches first, and it assumes only that the residual had been evaluated on a sufficiently fine grid.", "The lower root, since it is the first rate at which both curves can agree."]'::jsonb, 1, 'The compositeTwoCrossings golden makes the point in its own note, reporting 44.984487 stb/d marked stable no beside 1787.246675 stb/d marked stable yes.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 1, 'One reading taken at the left hand end of the scan settles how many solutions are possible. Which reading is it?', '["The depth of the residual minimum, read in psi.", "The sign of the residual at the lowest sampled rate, which fixes whether the count must be even or odd.", "The slope of the residual at the lowest sampled rate, since a falling residual there guarantees that a root lies above it.", "The gravity share carried by the tubing requirement at the lowest sampled rate."]'::jsonb, 1, 'The same reading is available before any solve, since it follows from the dead column set against the reservoir pressure.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 2, 'FORCADOS-3''s residual reads +575.820837 psi at 4.135950 stb/d. What has that established about the well?', '["Only that this rate is unavailable.", "That the wellhead pressure has been set too low.", "That the well is dead, because a tubing requirement above the reservoir supply at low rate cannot be overcome at any rate.", "That the well flows, but on the falling gravity limb of its tubing curve."]'::jsonb, 0, 'The well in fact carries two crossings, at 234.488087 and 2125.009203 stb/d, neither of which the low end reading could have located.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 3, 'Between 4.14 and 778.85 stb/d the FORCADOS-3 gravity term falls from 3333.187930 to 1718.108793 psi. What does friction do across that span?', '["It falls in step with the gravity term.", "It rises by rather more than the gravity term has fallen, which is what forces the required tubing pressure to turn upwards there.", "It rises from 0.001796 to 63.693936 psi, far too little to offset the weight the column has shed.", "It stays at zero, because friction only appears above the tubing minimum."]'::jsonb, 2, 'The reservoir gives up only 0.63615646 psi for every stb/d over that range, so the tubing sheds pressure the faster and the gap closes.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 4, 'Sampling FORCADOS-3 only near zero rate and reporting dead is wrong by how much, and what settles the matter properly?', '["By nothing, as that reading is a fair verdict.", "By 234.488087 stb/d, with the count of sign changes settling it.", "By the full open flow of 4135.949669 stb/d, with the dead column deciding.", "By 2125.009203 stb/d, and the minimum of the residual settles it where the end readings cannot."]'::jsonb, 3, 'From the two end readings alone that well and the golden deadWell case are indistinguishable, since both are positive at each end.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 5, 'Why does a report of 234.488087 stb/d at 3570.828888 psia raise no suspicion when it is read on its own?', '["It matches the well''s absolute open flow fraction.", "The curves genuinely agree there, and the reading looks like a tight well held back.", "The engine marks every crossing it returns as stable, so a reader has no label available to tell one root from another.", "The rate falls within the stable window, which is where a well would be expected to sit."]'::jsonb, 1, 'A flowing pressure of 3570.828888 psia against a reservoir pressure of 3720 psia leaves a drawdown small enough to look deliberate.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 6, 'Nudge FORCADOS-3 slightly above its lower root and the residual turns negative. What happens next?', '["The well accelerates and does not settle until the residual returns to zero at 2125.009203 stb/d.", "The well loads up and dies within a few minutes.", "The well settles back onto the lower root, because a negative residual is a shortfall that pulls the rate down again.", "The well oscillates about the lower root with a period set by the column."]'::jsonb, 0, 'Nudged the other way the residual is positive and the well slows with nothing below to catch it, so disturbances grow in both directions.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 7, 'A solver that reports the first sign change it meets on a two root well returns which value, and how far out is it?', '["It returns dead, since the two roots cancel.", "It returns 2125.009203 stb/d, the operating point, because the scan runs downwards from the absolute open flow end.", "It returns 234.488087 stb/d, the unstable root, low by the whole window width of 1890.521117 stb/d.", "It returns the mean of the two roots, so the error is half the window."]'::jsonb, 2, 'Nothing in the output announces the substitution, which is why the rule has to be applied before the number is read rather than after.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 8, 'How does the compositeTwoCrossings golden phrase its rule for picking the operating point?', '["The crossing found first, once the bracket has been refined.", "The crossing whose flowing pressure lies closest to the reservoir pressure at the node in question.", "The crossing that lies nearer the tubing minimum rate of the well.", "The reduction over the two crossings, not the first found."]'::jsonb, 3, 'It carries the rule in its own note and reports 44.984487 stb/d marked stable no beside 1787.246675 stb/d marked stable yes.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 9, 'What is thrown away by discarding the unstable root once the operating point is known?', '["The absolute open flow implied by the inflow fit.", "The threshold the well must be lifted above, which gas lift and unloading exist to clear.", "The measure of how hard the well is pushed back after a disturbance.", "The rate at which the tubing curve passes through its own minimum pressure."]'::jsonb, 1, 'That threshold moves with the boundary conditions, running from 234.488087 stb/d at a wellhead pressure of 960 psia upwards as the well is choked.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 10, 'FORCADOS-3''s window runs from 234.488087 to 2125.009203 stb/d. What are its width and its share of open flow?', '["A width of 1890.521117 stb/d, being 0.45709481 of the open flow.", "A width of 985.078572 stb/d, set by the residual minimum.", "A width of 2125.009203 stb/d, which is the whole span from shut in conditions up to the operating point of the well.", "A width of 1203.919667 stb/d, the figure the engine reports as a pressure span."]'::jsonb, 0, 'The interval also spans 1203.919667 psi, so the same window has a width in rate and a span in pressure that must not be confused.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 11, 'Width and depth are two different numbers describing the same window. What does each one measure?', '["Depth fixes the width, so only one of them need be reported.", "Width measures the pressure span across the window in psi, depth the corresponding span in rate over that interval.", "Width says how far the well can be displaced, depth how hard it is pushed back towards its operating point.", "Width is read on the rate axis and depth is the drawdown at the upper root."]'::jsonb, 2, 'FORCADOS-3 carries a depth of -509.628610 psi at 985.078572 stb/d inside a width of 1890.521117 stb/d, and neither number implies the other.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 12, 'Raising FORCADOS-3''s wellhead pressure from 860 to 1160 psia changes both the rate and the window. Which falls faster?', '["The dead column, which rises rather than falls with the choke.", "The rate, which drops from 2246.821833 stb/d to 1842.012114 stb/d, a larger proportional loss than the window suffers.", "Neither of them, since both fall by the same fraction of their starting value.", "The window, dropping from 2064.445505 to 1473.513228 stb/d."]'::jsonb, 3, 'A well that has given up a modest share of its rate may have given up a far larger share of its resilience, and only one of those appears in a rate report.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 13, 'FORCADOS-3 has a wide window and yet sits only 18.717814 psi above its tubing minimum. How can both be true?', '["The margin is quoted in psi and the window in stb/d.", "They measure different things, one a displacement along rate and one a position on the tubing curve.", "They cannot both be true, so the window must have been computed elsewhere.", "A wide window always implies a small pressure margin, as a matter of construction."]'::jsonb, 1, 'BONNY-7 reverses the pair exactly, with no window at all and an operating point 585.899719 psi clear of its own tubing minimum.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 14, 'Near tangency, what becomes of a well when its residual minimum is worsened by a small amount?', '["It heads, cycling between the two roots.", "It produces at a slightly lower rate, because the two roots move gently together and the operating point slides down.", "It stops, since losing the dip removes both roots at once.", "It keeps flowing but the crossing is relabelled as unstable by the engine."]'::jsonb, 2, 'The separation of two nearly coincident roots goes as the square root of the depth of the dip, so movement near zero is violent in both directions.'),
  ('nodal', 'advanced', 'module', 'm02-two-crossings', 15, 'What does the reported status show for a window of 1890.521117 stb/d and for one of 57.851719 stb/d?', '["Flowing, but with the crossing count reduced to one.", "Flowing for the wider window and marginal for the narrower one, which is exactly the warning the engine is there to give.", "Dead for the narrower window, because tangency is treated as no solution.", "Flowing in both cases, so the status carries no warning that the verdict has become fragile."]'::jsonb, 3, 'The narrow case is FORCADOS-3 choked to 1469.15 psia, where an ordinary looking 1014.239511 stb/d sits on a minimum residual of -0.478610 psi.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 1, 'Reading with increasing rate, which pair of residual signs around a crossing tells you the well returns to it?', '["Positive just below the crossing and negative just above it.", "Negative just below the crossing and positive just above it, so the residual is increasing through zero.", "Negative on both sides, since a surplus of pressure on either side is what pushes a displaced well back where it started.", "Whichever pair the engine reports, since the residual is zero at the crossing itself."]'::jsonb, 1, 'Nothing measured at the crossing can settle the verdict, because the residual is zero at the holding kind and at the failing kind alike.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 2, 'FORCADOS-3 reads +575.820837 psi at 4.135950 stb/d and +3284.465003 psi at its highest sampled rate. What would a verdict built on that pair conclude?', '["That no crossing exists at all, because the two signs agree, on a well that carries two of them.", "That the upper crossing holds and the lower one does not.", "That the well is stable, since a residual positive at both ends of the scan must be increasing through any root between them.", "That the well heads, since a positive residual at low rate signals a loading column."]'::jsonb, 0, 'A neighbourhood wide enough to contain both crossings hides both of them, which is why the test has to be read close in.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 3, 'Why does the lower of two crossings fail on every well that has two of them?', '["The lower crossing always sits left of the tubing minimum.", "Because the lower crossing carries less drawdown, leaving nothing in reserve to recover with.", "A dip descends through its first root and ascends through its second, so only the second is increasing.", "Because the solver refines the upper bracket more finely than the lower one."]'::jsonb, 2, 'The goldens carry the same ordering, with compositeTwoCrossings marked stable no at 44.984487 stb/d and stable yes at 1787.246675 stb/d.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 4, 'How is the stability condition stated in terms of the two curve slopes?', '["The outflow slope must be positive at the crossing rate.", "The outflow slope must exceed the inflow slope in magnitude, so a steeper tubing curve is what holds a crossing in place.", "The inflow slope must exceed the outflow slope, with both read as signed numbers.", "The outflow slope must exceed the inflow slope as signed numbers, both read at the crossing rate."]'::jsonb, 3, 'Written as a difference it is the derivative of the residual, which is the single quantity whose sign the whole test turns on.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 5, 'Which half of that comparison can be written down before the well is solved at all?', '["The inflow slope, which above the bubble point is fixed at minus one over the productivity index.", "The outflow slope, which is fixed by the tubing description.", "Neither, because both depend on the crossing rate, which is an output of the solve.", "The residual slope, since it is the difference the test actually compares."]'::jsonb, 0, 'That gives -0.50000000 psi per stb/d for BONNY-7 on an index of 2.00000000 stb/d/psi and -0.63615646 for FORCADOS-3 on 1.57194033.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 6, 'Why is a difference compared rather than the outflow slope being asked to carry a particular sign?', '["Because signs are unreliable when both curves have been fitted.", "Because the inflow slope is always negative and the outflow slope always positive, so their difference is positive in every case.", "Subtracting a negative inflow slope hands the crossing margin, so a falling outflow can still pass.", "Because the difference is what the engine computes, though either statement returns the same verdict."]'::jsonb, 2, 'The steeper the inflow, the more falling outflow a well tolerates, so a well with a poor reservoir is the more forgiving on this one point.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 7, 'BONNY-7 reads an inflow slope of -1.57442483 psi per stb/d at 4195 stb/d against -0.50000000 higher up its curve. What trips a reader who compares magnitudes?', '["The two readings belong to different curves and cannot be compared.", "The steeper reading is the larger magnitude and yet the smaller number, and the test compares numbers.", "Magnitudes are the right comparison here, and the error is instead that the two values were read at different rates.", "The steeper reading is the smaller magnitude, so a magnitude test would wrongly call the crossing stable."]'::jsonb, 1, 'That slope steepens below the bubble point, so the same well hands a different margin to a crossing depending on where it lands.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 8, 'What does the slope test return when the two slopes at a crossing are equal?', '["It returns a stable verdict, since equal slopes leave the residual flat at the crossing and a flat residual moves the well nowhere.", "It returns an unstable verdict, because equal slopes leave a displaced well no restoring pressure and it drifts away for good.", "It returns the wider of the two windows, because the engine falls back to comparing window widths whenever the slope difference vanishes.", "Nothing usable, since the residual slope is zero at tangency and the test does not resolve the case."]'::jsonb, 3, 'It is a local test throughout, so it also says nothing about how far a well can be displaced, which is what the window width measures.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 9, 'FORCADOS-3 has a heading crossing at 234.488087 stb/d. What does the model say a well nudged upwards from it does?', '["It accelerates through a residual that reaches -509.628610 psi and settles at 2125.009203 stb/d.", "It returns to the same rate of 234.488087 stb/d, because the friction the higher rate costs is what pushes the well back down to its crossing.", "It surges with a period and an amplitude the node model computes from the weight of the column standing above the perforations.", "It moves up to the tubing minimum rate of 1843.619418 stb/d and stops there, because the flat bottom of the tubing curve holds any rate that reaches it."]'::jsonb, 0, 'A nudge therefore buys a rise of 1890.521117 stb/d, which is exactly the width of the stable window on that well.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 10, 'Below the tubing minimum FORCADOS-3''s gravity term falls from 3333.187930 psi to 1298.616735 psi. Why does one small loss of rate make the next one more likely?', '["Because friction rises steeply as the rate falls in that region.", "Because the well crosses its tubing minimum on the way down, where the outflow slope is undefined.", "Each step down adds hundreds of psi of weight while the reservoir gives back only 0.63615646 psi per stb/d.", "Because the reservoir loses pressure faster than the column gains it, which widens the gap."]'::jsonb, 2, 'Friction charges almost nothing over that stretch, climbing only from 0.001796 psi to 176.176764 psi, so the weight term decides the whole movement.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 11, 'A colleague quotes a kick off threshold for FORCADOS-3 without saying what the wellhead was held at. What is wrong with that?', '["Nothing, since the threshold is a property of the reservoir alone.", "The threshold moves with the wellhead, and choking raises the floor while it lowers the ceiling.", "The threshold is only meaningful with the grid count beside it, because a coarse scan loses the lower crossing first.", "The threshold should be quoted against the bubble point rather than against any surface condition."]'::jsonb, 1, 'Its window reads 2064.445505 stb/d at a wellhead of 860 psia and 1473.513228 stb/d at 1160 psia, so both ends of the interval have moved.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 12, 'ESCRAVOS-9 flows at a stable crossing 792.375394 stb/d to the left of its tubing minimum. What does that instance settle?', '["That the engine mislabels crossings that sit on a falling limb.", "That a well left of its tubing minimum is stable whenever its outflow curve is still falling steeply enough to shed weight.", "That the tubing minimum was located wrongly, since a crossing on the falling limb cannot hold and this one is reported stable.", "That the side of the tubing minimum a well sits on is a correlation and not the stability test."]'::jsonb, 3, 'The engine''s own test agrees with the well, and it calls the second crossing at 456.989718 stb/d unstable on the same curves.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 13, 'ESCRAVOS-9 shows an outflow slope of -0.28613256 psi per stb/d against an inflow slope of -0.45150309. Why does the crossing hold?', '["The tubing hands back less on every stb/d than the reservoir gives up, so the gap widens with rate.", "Because both slopes are negative, and two curves falling together cannot pull apart, which is the arrangement a held crossing takes.", "Because the residual slope of 0.16537053 psi per stb/d is small, and a small residual slope is what a firmly held crossing shows.", "Because the outflow curve turns upward just above the operating rate, so a rise in rate is met by a column that costs more than the reservoir pays."]'::jsonb, 0, 'Its operating point sits 105.421380 psi above the bottom of its own tubing curve while remaining far to the left of it.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 14, 'Sampled minimum rates miss the true ones by -22.728631, -31.814966 and 42.892315 stb/d on the three teaching wells. What does that spread show?', '["The sampled curves need more points along the friction limb.", "The three wells were sampled at different counts, so the errors belong to the sampling and not to any curve shape.", "The landmark the shortcut relies on is badly located, and the error does not even keep one sign.", "The minimum rate is reliable, since the matching pressure errors are all below one psi."]'::jsonb, 2, 'Pressure is flat near a minimum, which is why those same three cases cost only 0.76036884, 0.25586360 and 0.27064549 psi.'),
  ('nodal', 'advanced', 'module', 'm03-stability', 15, 'ESCRAVOS-9 is reported stable at a wellhead of 480 psia. What does that word fail to carry?', '["That the crossing was located on a sampled rather than an exact curve.", "Its window is only 552.770229 stb/d wide, and a step to a wellhead of 560 psia leaves it dead.", "That the two crossings are 20 stb/d apart, the separation where classification fails.", "That the crossing is a maximum of the residual rather than a zero of it."]'::jsonb, 1, 'Its minimum residual is -23.748626 psi against -989.578610 psi on BONNY-7, and the reports carry the identical word.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 1, 'How does solveNodeCore actually search for a solution at the node?', '["It reads the crossing straight off the plotted curves.", "It follows the tubing curve downwards from the wellhead until the pressure it requires matches the reservoir supply.", "It minimises the squared residual over the rate range with a gradient method.", "It evaluates the residual on a grid of rates and looks for adjacent samples that carry opposite signs."]'::jsonb, 3, 'The grid runs from a small fraction of the absolute open flow up to just under it, and the documented default is 40 points.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 2, 'A status of dead comes back from the engine. What has actually been established?', '["That the well cannot flow at the current wellhead pressure.", "That no adjacent pair of samples had opposite signs.", "That the residual has been computed at every rate across the whole range and found positive at each one of them.", "That the tubing requirement exceeds the reservoir supply at the residual minimum."]'::jsonb, 1, 'It is a statement about the grid rather than about the well, so the residual itself has to be read before the verdict is accepted.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 3, 'Why can a well with only one crossing never be lost by a sign change scan?', '["Its residual changes sign once and keeps the new sign, so any pair spanning it must straddle it.", "The grid always places a node at the crossing itself.", "Its residual passes through zero steeply, and a steep root is always bracketed.", "Single crossing wells are solved by a direct formula rather than by a scan."]'::jsonb, 0, 'The exposure belongs entirely to the two crossing case, where the negative stretch has a finite width that can fall between neighbouring samples.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 4, 'What is the recorded defect in the documented default of 40 grid points?', '["Forty points is too few to converge the root to full precision.", "The grid starts at zero rate, where the residual is undefined for a Vogel inflow.", "Two crossings can sit inside a single interval, so a flowing well comes back dead with every residual correct.", "The residual is evaluated with too few sub-intervals in the column, so the tubing pressures used by the scan are wrong."]'::jsonb, 2, 'The defect is recorded rather than repaired, so any dead verdict from a shipped run carries it until the residual is inspected directly.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 5, 'Spacing on the rate grid is not something a user types in. What sets it?', '["The number of column sub-intervals used.", "The rate range divided by the count of points requested.", "A fixed default of 105.837892 stb/d, which the engine applies to every well irrespective of its absolute open flow.", "The width of the stable window, which the engine estimates before it scans."]'::jsonb, 1, 'On FORCADOS-3 the same counts give 105.837892 stb/d at 40 points and 20.742099 stb/d at 200, purely because its open flow is 4135.949669 stb/d.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 6, 'Spacing below the window width guarantees detection. What is guaranteed once the spacing is larger?', '["That the crossings are found but labelled the wrong way round.", "That the two crossings will be missed, because no sample can fall inside a window narrower than the spacing.", "That the well is reported dead until the count is raised past the threshold.", "Nothing at all, in either direction."]'::jsonb, 3, 'The guarantee is one sided, which is why choked FORCADOS-3 reads flowing at a ratio of 1.829468 and dead at 1.456107.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 7, 'The pinched analytic case returns dead at 40 points and dead again at 100. Why does 110 change the answer?', '["Spacing falls to 18.311927 stb/d, below the 20.000000 stb/d window that 20.161616 stb/d still exceeded.", "Above 100 points the engine switches to a bisection search.", "The extra points sharpen the root find, so the crossings at 990.000000 and 1010.000000 stb/d can finally be separated.", "The grid at 110 points happens to place one of its samples exactly on each root."]'::jsonb, 0, 'The sequence looks like an ordinary convergence threshold, which is what makes it such poor evidence that refinement is a remedy.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 8, 'Choked FORCADOS-3 is found at 40 points, lost at 50 and found again at 60. What explains that pattern?', '["The choked well drifts between runs, so the window is not the same each time.", "The grid is rebuilt rather than subdivided, so none of the 50 samples sits where any of the 40 samples sat.", "Fifty points is an even split of the range and 40 is not.", "The stability test is applied before the bracket is refined, so a coarse grid can reject a root a finer grid keeps."]'::jsonb, 2, 'Refining until the answer stops changing is therefore not a method here, because the answer is free to change back again.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 9, 'Which check settles a dead verdict without depending on where the samples happen to fall?', '["Checking that the operating point lies right of the minimum.", "Asking whether the residual ever goes negative, which costs the same per point and reports a margin.", "Repeating the scan at a much higher count and accepting agreement.", "Comparing the crossing count returned at two different wellhead pressures."]'::jsonb, 1, 'The published deadWell case survives that test with a smallest sampled residual of 988.172727 psi and nothing negative anywhere.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 10, 'What does one extra grid point cost the engine in work?', '["Nothing measurable in practice.", "One column traverse at 16 sub-intervals, whatever the well being solved.", "One residual evaluation plus a fresh root find on every interval, which makes the total grow as the square of the count.", "One residual evaluation, so the total is linear in the count."]'::jsonb, 3, 'Each evaluation is one inflow read and one outflow read, the latter carried at 16 sub-intervals on BONNY-7 and 24 on FORCADOS-3.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 11, 'Why can no fixed number of grid points be safe for every well?', '["The window has no lower bound, while the spacing depends only on open flow and the count of points.", "Because open flow changes as the reservoir pressure declines.", "Because the engine reduces the count automatically whenever the column integration needs more sub-intervals.", "Because a higher count always shifts the operating rate a little further."]'::jsonb, 0, 'Choking FORCADOS-3 walks its window from 2064.445505 stb/d down to 57.851719 stb/d with the reservoir untouched and the spacing unmoved.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 12, 'BONNY-7 returns 1355.714057 stb/d at 40 points and 1355.714058 stb/d at 4000. What produces that difference?', '["A change in the reported stability label at high counts.", "The column integration, which is given more sub-intervals at the higher count.", "Root find tolerance, not grid error.", "Grid error alone, which shrinks steadily as the spacing falls from 110.661425 stb/d to 1.079219 stb/d over those counts."]'::jsonb, 2, 'Refinement helps where the output is continuous in the discretisation, as column integration is, and not where it is a discrete alignment test.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 13, 'Detection and classification are the two stages of the routine. Which gives way first, and at what separation?', '["Detection, but only once the count is raised beyond 400.", "Detection, which fails on a spacing of 51.179487 stb/d while classification resolves 20 stb/d cleanly.", "Classification, which cannot tell the two roots apart once they close to 20 stb/d, however fine the grid becomes.", "Both stages fail together, since a bracket and its label are produced in one pass."]'::jsonb, 1, 'Tightening the stability criterion would not change a single dead verdict, so hardening the sophisticated stage buys nothing at all.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 14, 'A verdict that flips from flowing to dead and back as the count is raised identifies its own culprit. How?', '["Only an alignment test can be non monotone in the count, since a stability rule labels a root the same way.", "Because the open flow is recomputed for every new grid.", "Because the root find tolerance is reached at different counts on each run.", "Because a stability criterion inspects the residual on both sides of a root, which gets delicate."]'::jsonb, 0, 'That signature is worth learning, because it names the failing stage from the output alone with no access to the code.'),
  ('nodal', 'advanced', 'module', 'm04-the-scan-that-cannot-see', 15, 'Somebody writes 200 grid points into the workflow because it has always worked. What is wrong with that standard?', '["It leaves stability unverified.", "It fixes a spacing that no longer applies once the open flow is recomputed.", "It is defined against no property of any well.", "It is far too expensive to run routinely, given that each point costs a full column traverse in the engine."]'::jsonb, 2, 'On the pinched instrument the threshold sits between 20.161616 and 18.311927 stb/d against a window of 20.000000 stb/d, and a window a quarter as wide would defeat 200 points silently.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 1, 'BONNY-7 sits 585.899719 psi above its tubing minimum and FORCADOS-3 only 18.717814 psi, yet both report flowing and stable. What follows?', '["The two wells are equally comfortable, since the words agree.", "FORCADOS-3 is the better placed, being near the tubing minimum where lift is cheapest.", "The field that separates the two answers is the clearance to the shoulder rather than the status.", "The difference is a sampling artefact, since both shoulders were read off sampled curves."]'::jsonb, 2, 'Their fractions of open flow, 0.31350017 and 0.51378991, are just as blind to the difference as the status word is.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 2, 'Halving BONNY-7''s friction constant moves its tubing minimum from 627.069742 to 845.667814 stb/d. What does that do to an answer quoted a few psi above its own shoulder?', '["The shoulder moves past the answer, so the point does not shift slightly when the constant is wrong.", "Nothing, because the friction constant is a tubing property.", "The answer moves by the same few psi, since the shoulder and the operating point sit on one curve and travel together.", "The rate falls while the flowing pressure rises, as with any tubing change."]'::jsonb, 0, 'Doubling the same constant to 0.00128 takes the shoulder the other way, to 455.992990 stb/d and 1656.374688 psia.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 3, 'What is the specific error in reading a node rate quoted to nine figures as though it had been observed?', '["Nine figures exceed what the engine''s root find can actually resolve.", "It was computed from two models, one fitted to a single test and one built from three chosen constants.", "There is no error, because the residual is driven to zero at the crossing and a converged root is as good as a measurement.", "The rate is right but the flowing pressure beside it is not, since only one of the two survives a change of node."]'::jsonb, 1, 'The related error is letting the open flow reassure, since that is the rate at zero flowing pressure and no well is ever there.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 4, 'Why is wellhead pressure the axis a sweep is usually run on?', '["It is the only input the engine allows a user to vary in a sweep.", "It moves both curves at once, so the response is large enough to read against fitting noise.", "It is a condition rather than a decision, so it can be swept without committing to anything.", "An operator actually turns it, and it enters only the outflow curve, so every change is attributable."]'::jsonb, 3, 'The reservoir pressure and the bubble point are conditions rather than decisions, which is why neither of them is swept in the same spirit.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 5, 'Raising the wellhead pressure across a sweep makes the rate fall while the flowing pressure rises. Why?', '["The tubing curve bends upward as the wellhead is raised.", "The operating point stays on the inflow curve, and less rate is less drawdown at that same point.", "The inflow curve is lifted by the same amount as the outflow curve, so the crossing walks up and to the left along both.", "The reservoir pressure rises with the surface pressure once the well has been choked back."]'::jsonb, 1, 'Every psi added at the surface is therefore paid out of drawdown, which is what makes the trade legible at all.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 6, 'BONNY-7 holds a minimum rate of 627.069742 stb/d while its minimum pressure reads 1336.243252, 1406.243252, 1476.243252 and 1546.243252 psia. What does that show?', '["The wellhead pressure translates the outflow curve without bending it, so the shoulder rate is fixed.", "The tubing minimum is insensitive to every input a user can set.", "The sampled curve is too coarse to see the shoulder move, and it does move with the wellhead.", "The lightening constant is doing the work, since it alone fixes where the shoulder sits."]'::jsonb, 0, 'The dead column at zero rate tracks the same way, reading 2430, 2500, 2570 and 2640 psia across those four conditions.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 7, 'Choked to 1469.15 psia FORCADOS-3 shows a window of 57.851719 stb/d and a minimum residual of -0.478610 psi. What does coming back down to 1160 psia buy?', '["A proportional gain, matching the pressure change made.", "Very little, because the well is already near tangency and a curve that has nearly stopped meeting cannot be recovered by choke alone.", "It restores the operating point to the rising friction limb of the tubing curve, which is the whole of the recovery.", "It lifts the rate from 1014.239511 to 1842.012114 stb/d and opens the window to 1473.513228 stb/d."]'::jsonb, 3, 'Nowhere earlier in that sweep did a few hundred psi do anything of the kind, which is what makes the region worth finding.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 8, 'What is the cost of a further rise in wellhead pressure past tangency, and why is that cost not a number?', '["The rate falls to zero smoothly once the crossings meet, so the cost is the whole of the rate the well was making.", "The cost is the window rather than the rate, and a window can always be quoted, so the answer is a number after all.", "Both crossings vanish together, so there is no reduced rate and no degraded point left to quote.", "The cost is the difference between the last two swept rates, since the trace keeps its slope through tangency and can be stepped once more."]'::jsonb, 2, 'The derivative is enormous in one direction and undefined in the other, because on that side the quantity has ceased to exist.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 9, 'A uniform lift took the analytic residual at 1000.0000 stb/d from -40.000000 psi to -0.100000 psi. What did it do to the window?', '["It closed from 400 stb/d to 20 stb/d, because near a minimum a small shift moves the zeros far.", "It closed in proportion, from 400 stb/d to about 399 stb/d, because the window follows the size of the lift applied to the residual.", "It widened, since a residual nearer zero over a longer stretch of rate is one that crosses at two more distant places.", "It was unaffected, since a uniform lift moves the level of the residual and the roots are set by where the two curves cross."]'::jsonb, 0, 'The same lift changed the residual at 100.0000 stb/d only from 770.000000 psi to 809.900000 psi, which is where nothing at all happens.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 10, 'Why is the asymmetry near tangency a property of the geometry rather than a quirk of one well?', '["Because every teaching well in the course behaves in this way.", "A function is flat near its minimum, so any small vertical shift moves its zeros a long way sideways.", "Because the residual is a parabola in every case, and a parabola is the one shape whose roots respond in that manner.", "Because the tubing curve is a J, and a J always meets a falling inflow at a shallow angle."]'::jsonb, 1, 'The closed form pair makes the point without any well at all, its two instruments sharing an inflow curve and differing by one uniform lift.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 11, 'Two very different things return the same word when a swept condition yields no answer. What are they, and what tells them apart?', '["A dead reservoir and a dead column, told apart by the drawdown, since a reservoir at the column weight leaves none of it.", "A failed root find and a failed integration, told apart by raising the column step count until the pressure stops moving.", "A well below its kick off threshold and one above tangency, told apart by counting the crossings the scan returns.", "A residual positive everywhere and a window narrower than the spacing, told apart by the minimum."]'::jsonb, 3, 'The published deadWell case is the honest article, its smallest sampled residual standing at 988.172727 psi with nothing negative anywhere.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 12, 'Which comparison, made before any sweep is run, says whether a dead verdict on a well is even possible?', '["The dead column at zero rate set against the reservoir pressure, since below it there is one crossing.", "The open flow set against the highest rate on the scan.", "The spacing set against the window width, since a spacing below the window guarantees that a live well is found.", "The bubble point set against the test pressure, which decides the inflow family and so the shape."]'::jsonb, 0, 'BONNY-7 reads 2430, 2500, 2570 and 2640 psia against 2740 psia across its sweep, so every one of its conditions must return flowing.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 13, 'A sweep is drawn with its failing condition dropped and the remaining points joined up. What has that done?', '["It has improved the plot, since a missing point adds nothing.", "It invites a reader to interpolate straight across the one condition that carried the warning.", "It has understated the rate at every remaining condition, because a dropped point drags the fitted line down towards zero.", "It has shortened the trace, though rate falls smoothly to zero past that point, so the missing end is easy to read back in."]'::jsonb, 1, 'Rate does not fall smoothly to zero, since past tangency there is no crossing at all and therefore no rate to fall.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 14, 'The engine''s gas inflow read carries a chord bias of -1.477901 psi at 1328.9296 Mscf/d. Why can no sweep reveal it?', '["The bias is far too small to change any rate the engine reports.", "A sweep varies the wellhead pressure, and that bias sits in the outflow column instead.", "The bias reverses sign across the sweep, so the two halves of the trace hide it between them.", "The bias is the same at every step, so it cancels out of the shape of the trace and stays in its level."]'::jsonb, 3, 'At the low rate end of a strongly turbulent family the same defect reads -12.910810 psi, which in a node becomes a rate bias of -0.638815 Mscf/d.'),
  ('nodal', 'advanced', 'module', 'm05-sweeping-a-decision', 15, 'Two sweeps run through one base case are presented as an uncertainty analysis. What is wrong with that claim?', '["Two sweeps are too few, and a third axis would settle the matter.", "Nothing is wrong, since varying two inputs across their ranges is what an uncertainty analysis consists of in practice.", "There are no probabilities in it, and every point still assumes the base model is the right one.", "The two axes do not interact, so the surface between them is the sum of the two lines and needs no further runs."]'::jsonb, 2, 'Wellhead pressure interacts with tubing size and with the friction constant, so two lines through one case are two lines and not a surface.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 1, 'Minimum residuals of -989.578610, -509.628610 and -0.478610 psi, and one of +988.172727 psi, describe four wells. What does that column do that no status field can?', '["It grades the margin, ordering the four from comfortable through nearly tangent to genuinely dead.", "It fixes how many crossings each of the four wells carries.", "It reports where each minimum sits in rate, which is the reading a report needs when an operating point has to be defended.", "It shows which of the four were solved at the same grid count and are therefore comparable."]'::jsonb, 0, 'Three of those four report flowing and the fourth dead, so the words divide them into two groups where the numbers divide them into four.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 2, 'Which two comparisons fix the shape of a node problem before the crossings are read?', '["The open flow against the test rate, and the grid against it.", "The gravity term against the friction term at low rate, and the sampled tubing minimum against the true one at 20001 points.", "The dead column against the reservoir pressure for the count, and the spacing against the window.", "The inflow slope against the outflow slope, taken at each crossing rate in turn."]'::jsonb, 2, 'The second of the pair is awkward because the window is an output of the solve, which is why the residual has to be read as well.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 3, 'Why do the greatest sensitivity and the least reliable detection arrive at the same place?', '["Because a fine grid is slower and so is used less often there.", "One lift shallows the dip, runs the crossings together and closes the window, which is a single event.", "Because the stability test loses resolution as two crossings approach, so the labels and the detection fail together.", "Because the residual minimum rises, and a shallow residual is harder to evaluate accurately."]'::jsonb, 1, 'Classification is not the stage that gives way, since it labels crossings 20 stb/d apart correctly at any count it is handed.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 4, 'What decides which inflow family a node problem should be worked with?', '["The number of points the tubing curve happens to be sampled at.", "The reservoir pressure alone, since the family describes the drive and not any one measurement.", "Whichever family returns the larger open flow, since that widens the scanned range.", "Where the production test sits relative to the bubble point, since both crossings then sit on that curve."]'::jsonb, 3, 'A test above the bubble point returns a productivity index error of 0.00000000 stb/d/psi, while one below it can cost -0.01349877 stb/d/psi.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 5, 'Why write the absolute open flow down as soon as the inflow family has been settled?', '["It is the top of the rate range the solver scans, so it sets the spacing at whatever grid count is used.", "It is the rate the well produces with the choke fully open.", "It is the rate where the two curves are guaranteed to meet, so it brackets the point from above.", "It is the reading that decides whether the well has one crossing or two."]'::jsonb, 0, 'Choking a well closes its window while leaving that number alone, which is why the spacing does not follow the window down.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 6, 'The tubing minimum is located before the solve. Which of its two coordinates should not be trusted off a sampled curve?', '["The pressure, which is the flattest part of the whole curve.", "Neither, because a sampled curve reproduces both coordinates once the sample count has passed about thirty points.", "The rate, which is off by tens of stb/d while the matching pressure is right to a fraction of a psi.", "Both equally, since an error in one coordinate of a minimum is always matched in the other, the two being read from the same sampled point."]'::jsonb, 2, 'Rate is the coordinate crossings are compared against, so the unreliable half is the half the comparison actually uses.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 7, 'Which single error makes every field of a graded node answer wrong, and what catches it?', '["Quoting a wellhead pressure where a bottomhole pressure was asked.", "Solving at too coarse a grid, caught by refining the count until the reported operating rate stops moving.", "Using the wrong pressure unit, caught by comparing the answer against the reservoir pressure, which no flowing pressure can exceed.", "Reporting the first intersection returned, caught by asking which way the residual crosses zero."]'::jsonb, 3, 'It contaminates everything downstream, since the flowing pressure, the drawdown and the fraction of open flow are all read off that rate.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 8, 'A dead verdict is about to be written down. What does the checklist require beside it?', '["A second run at twice the grid count, taken as confirmation.", "The minimum residual, so the verdict rests on the residual rather than on any amount of refining.", "The stability label of the nearest crossing, since a dead well went unstable first.", "The fraction of open flow at the last condition that still returned a flowing answer."]'::jsonb, 1, 'The grid belongs in the report too, because a node result is a claim about the well and the solver together.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 9, 'What does a node solution earn that neither of its two curves provides on its own?', '["It turns two independent models into one prediction, a rate and a pressure a meter can refute.", "It proves that the tubing description was correctly chosen.", "It removes the dependence on the production test, since the crossing is fixed by the two curves and not by a measurement.", "It supplies a margin in psi that neither curve carries by itself, which is what makes the answer testable."]'::jsonb, 0, 'It also prices physical changes in the currency of rate, as when a wellhead of 280 psia gives 1424.991968 stb/d against 1319.581001 at 490 psia.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 10, 'The residual is positive at every rate and there is no crossing. What are the two physical answers?', '["Raise the grid count, then lower the wellhead pressure.", "Re-fit the inflow curve on a fresh production test, then re-run on a finer grid.", "Accept the verdict, since a residual positive everywhere is the end of the analysis.", "Lighten the column or add energy to it, which is gas lift in the first case and a pump in the second."]'::jsonb, 3, 'That verdict is a change of question rather than a conclusion, and no solver setting will find a crossing on the published dead case.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 11, 'Why does a pump leave the inflow relation untouched?', '["Because a pump is always installed above the perforations, so it sits outside the interval the inflow relation describes.", "What the reservoir delivers at a given sandface pressure does not depend on what stands above it.", "Because the pump raises the wellhead pressure rather than the bottomhole pressure, and only the wellhead sits outside the node.", "Because a pump adds rate without adding drawdown, so the operating point stays where it was on the inflow curve."]'::jsonb, 1, 'What it replaces instead is the outflow curve, which becomes a pump curve while the node stays where it was.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 12, 'What does gas lift do to the node picture?', '["It raises the pressure the reservoir can hold at the sandface, since the injected gas repressures the formation near the well.", "It replaces the outflow curve altogether, so the residual has to be rebuilt and the stability question no longer applies.", "It moves the outflow curve down, leaving the picture the same with injection depth and rate as choices.", "It removes the lower crossing, so a lifted well cannot head however it is operated, because lightening the column erases the loading limb."]'::jsonb, 2, 'Two curves, a residual, crossings, a window and a stability question all survive the change, which is why the tier transfers to it.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 13, 'Which term of the stability condition is free to be negative without threatening the verdict?', '["The outflow slope, which has only to exceed the inflow slope, so it may be falling on its own.", "The inflow slope, which is negative on every well in any case.", "Neither, since a verdict built on two negative slopes cannot distinguish a crossing that holds from one that does not.", "The residual slope, provided the two curves are close enough together at the crossing that the difference is within the solver''s resolution."]'::jsonb, 0, 'The inflow slope is negative everywhere, so subtracting it is what hands the crossing the margin the outflow slope may lack.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 14, 'What does a trace carry that a single converged answer cannot?', '["The grid count that each of the points along it was solved at.", "A probability for each condition, since a trace covers a range of inputs where a single answer covers only one.", "The true tubing minimum, which a single solve can only estimate off a sampled curve.", "The direction and the speed at which the margin is moving while the status word stays unchanged."]'::jsonb, 3, 'Four conditions reading windows of 2064.445505, 1890.521117, 1695.613297 and 1473.513228 stb/d all report the same two words.'),
  ('nodal', 'advanced', 'module', 'm06-the-expert-reading', 15, 'A node is solved perfectly on a well that should not have been drilled. What has the work produced?', '["A defensible answer, which is all that any model can offer, since the node has done exactly what it was asked to do.", "A precise account of a rate nobody wanted, since the solution does not improve the decision.", "An answer that is wrong, because a model calibrated on a poor well inherits that calibration into every field.", "A basis for gas lift, since a well of that kind is the usual candidate for it once the node has priced its shortfall in rate."]'::jsonb, 1, 'Rates and pressures are not value, and turning either into a decision needs a price, a cost, a duration and a discount rate.'),
  ('nodal', 'advanced', 'final', null, 1, 'Moving the cut from the tubing shoe to the wellhead, an engineer keeps both reported figures unchanged. Which one has survived the move?', '["The rate, because it is common to both cuts, while the pressure now belongs to a different depth entirely.", "Neither, since a change of node invalidates the whole solve.", "The pressure, because the reservoir supports the same value wherever the cut is taken, whereas the rate depends on the range scanned.", "Both of them, provided the wellhead pressure was held at the same value throughout each of the two solves."]'::jsonb, 0, 'A node result names a pressure at one depth, so the depth belongs in the report beside the value or the reader supplies their own.'),
  ('nodal', 'advanced', 'final', null, 2, 'Every residual the scan computed was arithmetically correct and every one came back positive. What has that established?', '["That the well is dead and the curves need no further reading.", "That the residual minimum is positive, since a correct sample set brackets it.", "That no sampled rate was available, which is a weaker claim than saying no rate at all is available.", "That the tubing requirement exceeds the reservoir supply at every rate in the scanned range."]'::jsonb, 2, 'A negative stretch narrower than the spacing contributes no sample and no sign change, so the minimum has to be sought on purpose.'),
  ('nodal', 'advanced', 'final', null, 3, 'Given only a loaded column of 2430 psia and a reservoir pressure of 2260 psia, what may be written down before any scan runs?', '["That the well is dead, since the column stands above the reservoir.", "That the residual starts positive, so the well has either two crossings or none and never exactly one.", "That one crossing exists above the lowest sampled rate, because a column lightens faster than a reservoir gives up pressure.", "That the well will need lift, because a deficit of 170 psi at zero rate cannot be recovered by the tubing."]'::jsonb, 1, 'That is ESCRAVOS-9, which flows at 1009.759948 stb/d with crossings at 456.989718 stb/d and 1009.759948 stb/d.'),
  ('nodal', 'advanced', 'final', null, 4, 'Two engineers solve one well at different cuts and report the same rate with different pressures. Which of them is in error?', '["The one who cut at the wellhead, since the engine places its node at the bottom of the tubing and nowhere else.", "The one whose rate is lower, because a deeper cut sees more of the reservoir and always returns the larger rate.", "Both, since a node solution is unique and any two correctly executed solves of one well must agree on every reported field.", "Neither, because a pressure is quoted at a depth and the two cuts name pressures at different depths."]'::jsonb, 3, 'Everything upstream of the cut becomes the inflow and everything downstream the outflow, so the split decides what each curve contains.'),
  ('nodal', 'advanced', 'final', null, 5, 'A study of tubing size is being set up. What does cutting at the tubing shoe give that a cut downstream of the choke would not?', '["One curve moves and the other holds still, so every change in the answer is attributable to the tubing.", "A shorter column, which lowers the truncation of the integration.", "A residual needing no wellhead pressure, since the boundary condition then sits inside the node rather than outside it.", "A wider stable window, because a choke inside the node no longer restricts the rate range being scanned."]'::jsonb, 0, 'Cut in the middle of what you want to study and it goes invisible, since both curves then move together on every step of the sweep.'),
  ('nodal', 'advanced', 'final', null, 6, 'The friction constant used for BONNY-7 turns out to be half the value entered. How much of the reported answer has to be redone?', '["Only the flowing pressure, as rate is fixed by the inflow curve.", "Only the stability verdict, since slopes depend on friction and values do not.", "All of it, since the shoulder itself moves from 627.069742 to 845.667814 stb/d and the answer sits against it.", "None of it, because friction is negligible at the operating rate and gravity carries the requirement."]'::jsonb, 2, 'Halving it also takes the minimum pressure from 1476.243252 to 1309.348403 psia, so a point a few psi above the shoulder can end below it.'),
  ('nodal', 'advanced', 'final', null, 7, 'FORCADOS-3''s inflow was fitted to a test taken below its bubble point and the solve converged cleanly. What does that convergence say about the fit?', '["That the fit is adequate, because a bad curve would fail to bracket.", "Nothing, since the solver tests only that the two curves agree, and it converges on a wrong curve as easily.", "That the fit is at least self consistent, because the productivity index backed out of the test reproduces the test rate exactly.", "That the composite and the straight line must agree at the operating point, whatever they do away from the test."]'::jsonb, 1, 'The straight line backs out 1.55844156 stb/d/psi against the composite''s 1.57194033 and an open flow of 5797.402597 against 4135.949669 stb/d.'),
  ('nodal', 'advanced', 'final', null, 8, 'A residual reads +168.022848 psi at the bottom of the scan and +1987.966491 psi at the top. Which single further reading settles the well?', '["The minimum of the residual, which for that well is -23.748626 psi and therefore puts two crossings on it.", "The dead column, which fixes the sign at the lowest rate.", "The inflow slope at the top of the scan, which fixes how many crossings the residual is permitted to have.", "The count of sign changes, since an even count between two positive readings distinguishes a dead well from a flowing one."]'::jsonb, 0, 'Identical signs at the two ends force an even number of crossings, and even means either zero or two rather than one.'),
  ('nodal', 'advanced', 'final', null, 9, 'A solver hands back 456.989718 stb/d at 2067.583276 psia and nothing in the report looks wrong. What has actually been returned?', '["A converged answer sitting at the tubing minimum of that well, which is where the requirement is lowest.", "A point below the absolute open flow and above the rate the well truly holds, so a plausible operating figure.", "An operating point on the falling gravity limb, unusual for a well of this kind but perfectly stable and correct as reported.", "The heading branch of that well, a genuine root sitting 552.770229 stb/d below the rate it holds."]'::jsonb, 3, 'A rate in the hundreds at a pressure near the reservoir reads as a tight well produced gently, so the figures raise nothing by themselves.'),
  ('nodal', 'advanced', 'final', null, 10, 'ESCRAVOS-9 carries a window of 552.770229 stb/d while its default scan spaces samples 83.870385 stb/d apart. What does that ratio license?', '["Nothing, as the guarantee needs the spacing above the window.", "A verdict that carries over to the same well behind a tighter choke.", "Detection is guaranteed on that well, since a spacing below the window forces at least one sample inside it.", "A precision claim on the operating rate, since a sample landing inside the window fixes the root to within one spacing."]'::jsonb, 2, 'The guarantee is one sided, so a ratio above one promises nothing in either direction rather than promising a miss.'),
  ('nodal', 'advanced', 'final', null, 11, 'One column of a report gives 552.770229 stb/d and another gives -23.748626 psi. Which of them says how hard the well is pushed back?', '["The residual minimum in psi, since depth measures the push while width measures the room to be displaced.", "The width in stb/d, because a wide window pushes harder.", "Both, since the two are proportional through the inflow slope.", "Neither, since the strength of the restoring push is given by the residual slope at the crossing."]'::jsonb, 0, 'ESCRAVOS-9 carries that width with only 23.748626 psi of depth, while BONNY-7 has no window at all and a minimum of -989.578610 psi.'),
  ('nodal', 'advanced', 'final', null, 12, 'A choke is tightened in equal steps and the two crossing rates close on one another. What does the step past their meeting produce?', '["A single crossing, which the solver then reports as a tangency carrying a stable window of zero width.", "No crossing at all, so the well stops rather than settling at some reduced rate below the last one.", "A crossing that survives but is no longer stable, since the residual slope through it has changed sign at the merge.", "The same rate at a higher flowing pressure, since drawdown falls."]'::jsonb, 1, 'The gap between two nearly coincident roots goes as the square root of the depth of the dip, so both roots leave together.'),
  ('nodal', 'advanced', 'final', null, 13, 'A nitrogen kick off is being sized for a loaded well. Which figure from the node solution sets what the job must clear?', '["The absolute open flow, which bounds every rate the well can reach and therefore bounds the size of the job.", "The minimum residual of the well, converted into a rate through the inflow slope taken at the crossing that holds.", "The tubing minimum rate, since a well lifted above its own shoulder sits on the rising friction limb and will hold itself there.", "The lower crossing rate, which means nothing unless the wellhead pressure it was computed at goes with it."]'::jsonb, 3, 'FORCADOS-3''s threshold moves with the choke, its window reading 2064.445505 stb/d at 860 psia against 1473.513228 stb/d at 1160 psia.'),
  ('nodal', 'advanced', 'final', null, 14, 'BONNY-7 has no window at all and yet stands 585.899719 psi clear of its tubing minimum. What follows for a displacement in rate?', '["It cannot be displaced at all, since a zero window means zero room.", "It heads, because a well without a window has no basin to return to.", "It returns from any displacement downwards, because its residual is negative below the crossing at every rate.", "Its clearance in psi acts as the window, so the well tolerates displacement in proportion to the 585.899719 psi it carries."]'::jsonb, 2, 'A window exists only where there are two crossings, so its absence on a single crossing well is a statement about the count.'),
  ('nodal', 'advanced', 'final', null, 15, 'Both curves are falling at a crossing, the tubing at -0.10401749 and the reservoir at -0.50550508 psi per stb/d. What is the verdict?', '["It holds, because subtracting the steeper fall leaves a residual increasing at 0.40148759 psi per stb/d.", "Unstable, since a falling tubing requirement cannot restore a well.", "It holds, but only until the crossing reaches the tubing minimum.", "Undecided, because the test compares slope magnitudes and the reservoir carries the larger."]'::jsonb, 0, 'A steep inflow is a gift to the test, handing the well the whole of its own slope as margin before the tubing is asked for anything.'),
  ('nodal', 'advanced', 'final', null, 16, 'Two slopes are read at 1861 and at 3102 stb/d, then subtracted to produce a stability verdict. Why does that verdict belong to no crossing?', '["Because slopes interpolate badly while values interpolate well.", "The condition is local, so both slopes have to be evaluated at one rate, the rate of the crossing itself.", "Because the inflow slope moves from -0.63615646 to -0.90914074 psi per stb/d over that span, so the pair straddles the bubble point.", "Because the residual slope has to be read at the tubing minimum rather than at either of the two rates used."]'::jsonb, 1, 'FORCADOS-3''s outflow slope changes sign between those two rates, so a difference built from the pair describes a well that does not exist.'),
  ('nodal', 'advanced', 'final', null, 17, 'Surging is seen at surface every few minutes and the node model is asked to reproduce its period. What can the model deliver?', '["The period, from the residual slope at the unstable crossing.", "Nothing at all, because a heading well has no equilibrium anywhere.", "The amplitude, since the well runs between the heading crossing and the operating point and those two rates bound the swing.", "Only that an equilibrium exists which the well will not hold, with no period, amplitude or duration in it."]'::jsonb, 3, 'Heading is what a real well does instead of holding an equilibrium it cannot hold, and steady state arithmetic carries no clock.'),
  ('nodal', 'advanced', 'final', null, 18, 'The checklist asks that a stable crossing sit right of the tubing minimum, and ESCRAVOS-9 fails it while flowing. Which one is authoritative?', '["The geometric check, so the flow reported on that well must be an artefact of the tubing description used.", "The checklist, because it was written to be independent of the solver and so cannot be contradicted by it.", "The slope difference, since the geometric check confirms the usual case rather than defining stability.", "Neither on its own, because a verdict needs the two to agree and a disagreement means the tubing description is wrong."]'::jsonb, 2, 'ESCRAVOS-9 holds 792.375394 stb/d to the left of a minimum at 1802.135341 stb/d, and the engine''s own test agrees that it holds.'),
  ('nodal', 'advanced', 'final', null, 19, 'Eighty psi more at the wellhead takes ESCRAVOS-9 from a stable 1009.759948 stb/d to a status of dead. Which reported field warned of it?', '["The window of 552.770229 stb/d beside a residual minimum of -23.748626 psi, both of them small margins.", "The status field, which had read stable rather than flowing.", "The drawdown of 430.227950 psi, which had already used most of the reservoir.", "The clearance of 105.421380 psi above the tubing minimum, which is the margin any wellhead change spends before the others."]'::jsonb, 0, 'Wellhead pressure translates the tubing curve without bending it, so the same 80 psi is added to the requirement at every rate.'),
  ('nodal', 'advanced', 'final', null, 20, 'One well is solved twice, on a straight line inflow and on a composite, and both runs mark the crossing stable. What has been checked?', '["That the productivity index backed out of the test is the right one.", "Nothing about the fit, since the test reads only the two slopes at the crossing the chosen curve produced.", "That the fit is at least admissible, because an inflow curve inconsistent with the test would produce no crossing to classify.", "That both of the families agree at the operating point to within whatever tolerance the root find was given."]'::jsonb, 1, 'FORCADOS-3''s straight line reads 5797.402597 stb/d of open flow against the composite''s 4135.949669, and each converges cleanly.'),
  ('nodal', 'advanced', 'final', null, 21, 'At the instant a choked well''s two crossings merge, what happens to the slope test, and what still carries information?', '["It returns unstable, and only the operating rate remains useful.", "It is not evaluated, since the engine reports dead before classifying.", "It fails to resolve, while the residual minimum and the window, both at zero, still describe the well.", "It returns stable, because the merged root inherits the label of the upper crossing."]'::jsonb, 2, 'The residual''s slope at a tangency is zero, which is the one case where the difference of the two slopes settles nothing at all.'),
  ('nodal', 'advanced', 'final', null, 22, 'Detection has to be certified down to a window of 40 stb/d on a well whose open flow is 4135.949669 stb/d. What does that requirement fix?', '["The grid count, because spacing is the rate range divided by the count and must be brought under 40 stb/d.", "The wellhead pressure, which is what sets the window width.", "The column step count, since the residual is only as good as the traverse.", "Nothing, since the window is an output of the solve and cannot be known before the scan that is meant to find it has run."]'::jsonb, 0, 'That well spaces samples 41.693715 stb/d apart at 100 points and 20.742099 stb/d at 200, so 200 clears the requirement and 100 does not.'),
  ('nodal', 'advanced', 'final', null, 23, 'A run at 50 grid points calls a well dead where the 40 point run had it flowing. Which of the two runs should be believed?', '["The finer one, because a smaller spacing can only ever see more of the residual than a coarser one managed.", "Whichever of the two agrees with a third run taken at a far higher count than either of them had used before.", "The coarser one, since the finer grid has moved every sample and can no longer be compared with the run that preceded it.", "Neither by itself, since the residual minimum decides the matter and costs the same per point to obtain."]'::jsonb, 3, 'The grid is rebuilt rather than subdivided, so none of the 50 samples sits where any of the 40 samples sat.'),
  ('nodal', 'advanced', 'final', null, 24, 'Two integers sit on the settings panel, the count of grid points and the count of column steps. Which one rewards refinement?', '["Both, since each one reduces a discretisation error of its own.", "The column steps, whose output is continuous in the discretisation and converges from 2 steps upwards.", "The grid points, because halving the spacing halves the worst case error in the located crossing rate on any well at all.", "Neither, because both counts are alignment tests rather than approximations to a continuous quantity at all."]'::jsonb, 1, 'FORCADOS-3''s column reads 2600.819216 psia at 2 steps and 2608.360298 at 256, a truncation falling from -7.54108245 psi to zero.'),
  ('nodal', 'advanced', 'final', null, 25, 'A team proposes to certify the solver by raising the count until the verdict stops changing. Why does that not close the question?', '["Because the root find, not the grid, fixes the reported rate.", "Because the engine caps the count, so the sequence cannot be continued.", "The verdict is not monotone in the count, so an answer that has settled is free to change back again.", "Because the cost grows with the count, so the procedure stops for reasons of expense long before it reaches a safe spacing."]'::jsonb, 2, 'Choked FORCADOS-3 is found at 40 points, lost at 50 and found again at 60, and no classification rule can behave that way.'),
  ('nodal', 'advanced', 'final', null, 26, 'Effort is available to harden exactly one stage of the routine. Which stage should receive it, and what would the other buy?', '["Detection, because a tighter stability criterion would not change a single dead verdict the scan produced.", "Classification, since the stability label is what a reader acts on.", "Either, because the two stages fail at roughly the same separation.", "Detection, though a tighter stability criterion would also recover the wells lost at 50 grid points."]'::jsonb, 0, 'Classification labels roots 20 stb/d apart correctly at any count, while detection gives way at a spacing of 51.179487 stb/d.'),
  ('nodal', 'advanced', 'final', null, 27, 'Why does a sample that fell inside a narrow window at one count not survive to the next count up?', '["Because the engine drops the endpoints when the count rises.", "Because the samples are spaced evenly in pressure rather than in rate.", "Because the window itself moves when the count changes, since the solver re-evaluates the crossings before it lays out the grid.", "The grid is built afresh from the rate range and the new count, so no earlier sample position is kept."]'::jsonb, 3, 'Below the guarantee threshold the verdict turns on an alignment that has nothing to do with the well being studied.'),
  ('nodal', 'advanced', 'final', null, 28, 'A wellhead sweep is run at a fixed 40 grid points while the window closes along it. Where do its verdicts stop deserving trust?', '["At the open end of the sweep, where the rate is highest and the spacing between samples is coarsest.", "At the choked end, where the window has fallen below a spacing that never moved during the sweep.", "Nowhere, provided the first condition of the sweep was checked against a finer grid and returned the same operating rate.", "At both ends equally, since the spacing depends only on the open flow and the count of points used."]'::jsonb, 1, 'Spacing follows from the open flow and the count alone, so choking closes the window while leaving the instrument exactly as coarse.'),
  ('nodal', 'advanced', 'final', null, 29, 'Windows of 2064.445505, 1890.521117, 1695.613297 and 1473.513228 stb/d come out of a rising wellhead sweep. What does that column predict?', '["That the rate will reach zero smoothly a few steps further on.", "That the well is losing resilience in exact step with the rate it gives up at each swept condition of the sweep.", "That a later reversal buys more the further the sweep has gone, since the payoff grows as the window shrinks.", "That the window keeps falling by roughly 200 stb/d for each further 100 psia, so tangency can be located by extrapolation."]'::jsonb, 2, 'Coming back to 1160 psia from 1469.15 psia takes the well from 1014.239511 to 1842.012114 stb/d, which no earlier step of that size did.'),
  ('nodal', 'advanced', 'final', null, 30, 'Coming down at the choke returns a well from 1014.239511 to 1842.012114 stb/d. Why can the opposite move not be quoted as a loss of rate?', '["Past tangency there is no crossing, so there is no rate to subtract from and the loss is not a quantity.", "Because the loss would depend on the grid used to find it.", "Because the reservoir pressure would also have changed by then.", "Because the rate falls to zero continuously, so any figure quoted would depend on exactly where the sweep happened to stop."]'::jsonb, 0, 'The derivative is enormous coming down and undefined going up, since on that side the quantity being differentiated does not exist.'),
  ('nodal', 'advanced', 'final', null, 31, 'A gas sweep gives 11648.073706 Mscf/d at 500 psia, 11335.720032 at 800 psia and 9039.419053 at 1800 psia. What does the last step warn against?', '["Quoting a gas rate in Mscf/d when the node was solved in stb/d.", "Choking a gas well below 1200 psia, where the response turns over.", "Sweeping wellhead pressure on a gas well at all, since a gas tubing curve has no minimum.", "Extrapolating the early steps, since the same lift walks the crossing much further once the inflow flattens."]'::jsonb, 3, 'Early on the tubing curve rises through a steep part of the inflow, so the crossing barely moves against an open flow of 13289.296319 Mscf/d.'),
  ('nodal', 'advanced', 'final', null, 32, 'Minimum rates of 561.403918, 627.069742, 646.294276 and 581.492476 stb/d come from sweeping the lightening constant. What would two points conclude?', '["The right answer, provided the two points bracket the turn.", "The wrong sign, because the response turns over and a slope taken across the turn hides that entirely.", "Nothing at all, since the lightening constant enters the gravity term only and cannot move the tubing minimum rate.", "The right magnitude with the wrong units, as the axis is in stb/d."]'::jsonb, 1, 'FORCADOS-3 turns over the same way, reading 1607.279673, 1843.619418, 1987.819717 and 1928.734780 stb/d across the same four values.'),
  ('nodal', 'advanced', 'final', null, 33, 'The last flowing condition of a sweep reaches an operator as the maximum backpressure the well will take. What is that limit a claim about?', '["The tubing, whose minimum requirement is the value the wellhead pressure is eventually raised right past.", "The choke, which is the only piece of hardware the sweep moved and therefore the only candidate for a limit.", "The grid, since the next condition was called dead by a scan and not by any reading of the residual.", "The reservoir, because the limit is reached when the flowing pressure has risen to meet the reservoir pressure itself."]'::jsonb, 2, 'A sweep of choked FORCADOS-3 at 50 grid points calls 1469.15 psia dead where the well in fact produces 1014.239511 stb/d.'),
  ('nodal', 'advanced', 'final', null, 34, 'A trace of rate against wellhead pressure is offered as the case for changing a separator setting. What is still missing from it?', '["A price, the cost of the change, a duration and a discount rate, none of which live in a node model.", "A second axis, since one line cannot describe a surface.", "The stability verdict at each of the swept conditions, which a trace of rate against pressure leaves out.", "A probability attached to each point, which is what would turn a trace into the uncertainty analysis it resembles."]'::jsonb, 0, 'Rates and pressures are not value, and a sweep also holds still every axis it is not sweeping.'),
  ('nodal', 'advanced', 'final', null, 35, 'A choke study concludes that a well is safe for the next two years. Which condition moving on its own defeats that conclusion?', '["The wellhead temperature, which sets the gravity term.", "The bubble point, which falls as the reservoir is produced.", "The friction constant, which grows as the tubing scales up and eventually pushes the operating point onto the falling limb.", "The reservoir pressure, whose decline moves the inflow curve by more than any choke setting can."]'::jsonb, 3, 'A straight line well taken from 3200 psia to 2000 psia has a future absolute open flow of 3600.000000 stb/d, with nobody touching the surface.'),
  ('nodal', 'advanced', 'final', null, 36, 'A candidate solves the node first and picks the inflow family afterwards, choosing the one nearest the answer. What has that spoiled?', '["Only the stability label, which depends on the inflow slope.", "The drawdown, since the reservoir pressure is family dependent.", "The scan itself, because the family fixes the open flow that sets the top of the rate range the solver sweeps.", "Nothing much, provided the chosen family reproduces the production test as all three of them do."]'::jsonb, 2, 'Both crossings are judged against the curve that was built, so a family chosen to suit the answer can no longer test it.'),
  ('nodal', 'advanced', 'final', null, 37, 'A submission labels the lower of two crossings as the operating point. Which check catches that without the solver being run again?', '["The count of crossings, which must be even on such a well.", "The sign pair around each root, since the residual passes upward through zero only at the one that holds.", "The drawdown, which at the lower crossing is far larger than the reservoir pressure and the flowing pressure together allow.", "The fraction of open flow, which cannot exceed one at an operating point."]'::jsonb, 1, 'That error contaminates every field downstream, and on FORCADOS-3 it puts 234.488087 stb/d where 2125.009203 stb/d belongs.'),
  ('nodal', 'advanced', 'final', null, 38, 'A meter reads well under the rate the model predicted. What has the node solution earned in that exchange?', '["It turned two independent models into one claim a meter could refute, which neither curve offers alone.", "Nothing at all, since a prediction the meter refutes has no further value to the analysis that produced it.", "A stability verdict, since a well that meters steadily across a shift is holding the crossing it was given.", "A calibration, because the measured rate can be substituted for the production test and the inflow family refitted at once."]'::jsonb, 0, 'The inflow was fitted to a test and the outflow built from a tubing description, and only together do they name a rate and a pressure.'),
  ('nodal', 'advanced', 'final', null, 39, 'A dead verdict has been confirmed by reading the residual minimum. What kind of question does the work now become?', '["A closed one, since no solver setting will find a crossing.", "A reservoir question, because only a higher reservoir pressure could restore a well the residual has condemned.", "A question about the grid, since a confirmed dead verdict still depends on the rate range the scan was handed.", "A choice between lightening the column and adding energy to it, with the node picture unchanged either way."]'::jsonb, 3, 'Gas lift moves the outflow curve down and adds injection depth and rate as choices, while a pump replaces the outflow with a pump curve.'),
  ('nodal', 'advanced', 'final', null, 40, 'A shoulder read off a sampled curve is out by 42.892315 stb/d and by 0.27064549 psi. Which entry on the checklist does that threaten?', '["The minimum residual, which is read at the shoulder rate.", "The units row, since a rate error and a pressure error are not comparable.", "The crossing count, because the dead column comparison is taken at the shoulder pressure and inherits its error.", "The comparison of a crossing against the minimum rate, since it is the rate coordinate that is unreliable."]'::jsonb, 3, 'The error does not even keep one sign across the teaching wells, reading -22.728631 and -31.814966 stb/d on the other two.'),
  ('nodal', 'advanced', 'final', null, 41, 'Two candidates report identical rates and pressures, one stating the grid used and one not. What does the stated grid add?', '["It fixes the precision of the reported rate to the spacing.", "It makes the answer a claim about the well and the solver together, so a dead verdict can be audited.", "It lets the reader reproduce the run exactly, which is the only difference between the two.", "It shows that the count was raised until the answer settled."]'::jsonb, 1, 'The count buys detection rather than digits, since BONNY-7 returns 1355.714057 stb/d at 40 points and 1355.714058 at 4000.'),
  ('nodal', 'advanced', 'final', null, 42, 'Halfway through a graded answer the absolute open flow is found to be wrong. Which part of the work is affected first?', '["The stability verdict, which is read from the two slopes taken at the crossing the scan had returned.", "The drawdown at the node, which is reported as a fraction of the open flow and moves whenever it does.", "The rate range the scan covers, so every sampled rate and the spacing between them change with it.", "The tubing minimum, since the shoulder is located as a fraction of the open flow and moves whenever that figure moves."]'::jsonb, 2, 'The grid runs from a small fraction of the open flow up to just under it, so a wrong ceiling changes the instrument and the answer alike.');
